# Archetypes: id → (name, keywords, audience, objective, priors, core entities, extra screens, capabilities)
# priors: sophistication, trust, complexity, density, collaboration, transaction, navigation, mobile (0-100)
def _p(soph, trust, cx, dens, collab, tx, nav, mob):
    return {"sophistication": soph, "trust": trust, "complexity": cx, "density": dens,
            "collaboration": collab, "transaction": tx, "navigation": nav, "mobile": mob}

